SOURCE = '\ndef advance(s:readbuf,o:mutbuf,w:mutbuf) -> u32:\n    phase=get(w,0)\n    result=get(w,8)\n    if phase==0:\n        if get(w,H_HTTP_SIZE)>16777728:\n            return 0\n        if get(w,CR_RAW_USED)==get(w,CR_RAW_N):\n            return call(o,w,107,45,get(w,CR_FD),H_IO,1,66,0,0,12)\n        return call(o,w,1,228,0,H_IO,0,0,0,0,12)\n    if phase==107:\n        if result==NEG4:\n            return call(o,w,107,45,get(w,CR_FD),H_IO,1,66,0,0,12)\n        if result==0 or (failed(result) and result!=NEG11):\n            return close_conn(w)\n        return call(o,w,1,228,0,H_IO,0,0,0,0,12)\n    if phase==1:\n        if failed(result):\n            return 0\n        end=headers(w,H_IO+8192,get(w,H_IO))\n        put(w,H_HTTP_HEADER_N,end-(H_IO+8192))\n        put(w,H_HTTP_USED,0)\n        put(w,H_HTTP_REPLY_N,get(w,H_HTTP_HEADER_N))\n        if get(w,CR_HEAD)==0:\n            put(w,H_HTTP_REPLY_N,get(w,H_HTTP_REPLY_N)+get(w,H_HTTP_SIZE))\n        end=text_reply_name(w,H_IO)\n        store(w,end,0)\n        return call(o,w,2,319,H_IO,3,0,0,0,0,3)\n    if phase==2:\n        if failed(result):\n            return close_conn(w)\n        put(w,CR_REPLY_FD,result)\n        return write_header(o,w)\n    if phase==3:\n        if result==NEG4:\n            return write_header(o,w)\n        if failed(result) or result==0 or result>get(w,H_HTTP_HEADER_N)-get(w,H_HTTP_USED):\n            return close_conn(w)\n        put(w,H_HTTP_USED,get(w,H_HTTP_USED)+result)\n        if get(w,H_HTTP_USED)<get(w,H_HTTP_HEADER_N):\n            return write_header(o,w)\n        put(w,H_HTTP_USED,0)\n        return write_body(o,w)\n    if phase==4:\n        if result==NEG4:\n            return write_body(o,w)\n        if failed(result) or result==0 or result>get(w,H_HTTP_SIZE)-get(w,H_HTTP_USED):\n            return close_conn(w)\n        put(w,H_HTTP_USED,get(w,H_HTTP_USED)+result)\n        return write_body(o,w)\n    if phase==5:\n        if failed(result):\n            return close_conn(w)\n        put(w,CR_REPLY_N,get(w,H_HTTP_REPLY_N))\n        put(w,CR_REPLY_SENT,0)\n        put(w,CR_STATUS,3)\n        return epoll_conn(o,w,6,8196)\n    if phase==6:\n        if failed(result):\n            return close_conn(w)\n        return save_conn(w,get(w,H_HTTP_CONTINUE_MODULE),get(w,H_HTTP_CONTINUE_PHASE))\n    if phase==100:\n        if get(w,CR_FLAGS)&256!=0:\n            put(w,CR_STATUS,4)\n            return epoll_conn(o,w,105,8193)\n        return call(o,w,101,3,get(w,CR_REPLY_FD),0,0,0,0,0,0)\n    if phase==105:\n        if failed(result):\n            return close_conn(w)\n        return save_conn(w,HTTP_IO,3)\n    if phase==106:\n        put(w,CR_CHUNK_FD,NONE)\n        return restart(o,w)\n    if phase==101:\n        put(w,CR_REPLY_FD,NONE)\n        if get(w,CR_KEEP)==0 or get(w,CR_PEER_EOF)==1 or get(w,CR_CLOSE_DELIMITED)==1:\n            return close_conn(w)\n        if get(w,CR_BODY_FD)!=NONE:\n            return call(o,w,102,3,get(w,CR_BODY_FD),0,0,0,0,0,0)\n        return close_chunk(o,w)\n    if phase==102:\n        put(w,CR_BODY_FD,NONE)\n        return close_chunk(o,w)\n    if phase==103:\n        if failed(result):\n            return close_conn(w)\n        return epoll_conn(o,w,104,8193)\n    if phase==104:\n        if failed(result):\n            return close_conn(w)\n        put(w,CR_STATUS,0)\n        put(w,CR_RAW_N,0)\n        put(w,CR_RAW_USED,0)\n        put(w,CR_BODY_N,0)\n        put(w,CR_HEADER_N,0)\n        put(w,CR_HEAD,0)\n        put(w,CR_TASK_SLOT,NONE)\n        put(w,CR_DEADLINE,get(w,H_NOW)+30000000000)\n        return save_conn(w,HTTP_IO,3)\n    return 0\n\ndef write_header(o:mutbuf,w:mutbuf) -> u32:\n    used=get(w,H_HTTP_USED)\n    return call(o,w,3,18,get(w,CR_REPLY_FD),H_IO+8192+used,get(w,H_HTTP_HEADER_N)-used,used,0,0,12)\n\ndef write_body(o:mutbuf,w:mutbuf) -> u32:\n    if get(w,H_HTTP_USED)==get(w,H_HTTP_SIZE) or get(w,CR_HEAD)==1:\n        if get(w,H_HTTP_TYPE)==3 and get(w,CR_FLAGS)&256!=0:\n            return enter(w,HTTP_RESPONSE,5)\n        return call(o,w,5,72,get(w,CR_REPLY_FD),1033,15,0,0,0,0)\n    used=get(w,H_HTTP_USED)\n    return call(o,w,4,18,get(w,CR_REPLY_FD),get(w,H_HTTP_BODY)+used,get(w,H_HTTP_SIZE)-used,get(w,H_HTTP_HEADER_N)+used,0,0,12)\n\ndef restart(o:mutbuf,w:mutbuf) -> u32:\n    if get(w,CR_RAW_USED)<get(w,CR_RAW_N):\n        return enter(w,HTTP_BODY,300)\n    return call(o,w,103,77,get(w,CR_RAW_FD),0,0,0,0,0,0)\n\ndef headers(w:mutbuf,at:u64,seconds:u64) -> u64:\n    put(w,CR_CLOSE_DELIMITED,0)\n    if get(w,CR_VERSION)==1:\n        at=text_version10(w,at)\n    else:\n        at=text_version(w,at)\n    at=decimal(w,at,get(w,H_HTTP_STATUS))\n    at=text_space(w,at)\n    at=reason(w,at,get(w,H_HTTP_STATUS))\n    at=text_crlf(w,at)\n    if get(w,H_HTTP_TYPE)==1:\n        at=text_plain(w,at)\n    elif get(w,H_HTTP_TYPE)==2:\n        at=text_json(w,at)\n    elif get(w,H_HTTP_TYPE)==3:\n        at=text_sse(w,at)\n    if get(w,H_HTTP_ALLOW)==1:\n        at=text_allow_health(w,at)\n    elif get(w,H_HTTP_ALLOW)==2:\n        at=text_allow_mcp(w,at)\n    elif get(w,H_HTTP_ALLOW)==3:\n        at=text_allow_post(w,at)\n    if get(w,H_HTTP_TYPE)==3:\n        if get(w,CR_FLAGS)&2!=0:\n            at=text_session_id(w,at)\n            at=copy_state(w,CR_UUID,at,36)\n            at=text_crlf(w,at)\n        if get(w,CR_VERSION)==1:\n            put(w,CR_CLOSE_DELIMITED,1)\n        else:\n            at=text_chunked(w,at)\n    else:\n        at=text_length(w,at)\n        at=decimal(w,at,get(w,H_HTTP_SIZE))\n        at=text_crlf(w,at)\n    if get(w,CR_VERSION)==1:\n        if get(w,CR_KEEP)==1:\n            at=text_keep(w,at)\n    elif get(w,CR_KEEP)==0:\n        at=text_close(w,at)\n    at=text_date(w,at)\n    at=date(w,at,seconds)\n    return text_end(w,at)\n\ndef date(w:mutbuf,at:u64,seconds:u64) -> u64:\n    days=seconds//86400\n    remainder=seconds%86400\n    at=weekday(w,at,(days+4)%7)\n    at=text_comma_space(w,at)\n    year=1970\n    while days>=year_days(year):\n        days=days-year_days(year)\n        year=year+1\n    month=1\n    while days>=month_days(month,year):\n        days=days-month_days(month,year)\n        month=month+1\n    at=two(w,at,days+1)\n    at=text_space(w,at)\n    at=month_name(w,at,month)\n    at=text_space(w,at)\n    at=decimal(w,at,year)\n    at=text_space(w,at)\n    at=two(w,at,remainder//3600)\n    at=text_colon(w,at)\n    at=two(w,at,(remainder%3600)//60)\n    at=text_colon(w,at)\n    at=two(w,at,remainder%60)\n    return text_gmt(w,at)\n\ndef two(w:mutbuf,at:u64,value:u64) -> u64:\n    store(w,at,48+value//10)\n    store(w,at+1,48+value%10)\n    return at+2\n\ndef year_days(year:u64) -> u64:\n    if year%4==0 and (year%100!=0 or year%400==0):\n        return 366\n    return 365\n\ndef month_days(month:u64,year:u64) -> u64:\n    if month==2:\n        return year_days(year)-337\n    if month==4 or month==6 or month==9 or month==11:\n        return 30\n    return 31\n\ndef reason(w:mutbuf,at:u64,value:u64) -> u64:\n    if value==100:\n        return text_reason_100(w,at)\n    if value==200:\n        return text_reason_200(w,at)\n    if value==202:\n        return text_reason_202(w,at)\n    if value==204:\n        return text_reason_204(w,at)\n    if value==400:\n        return text_reason_400(w,at)\n    if value==401:\n        return text_reason_401(w,at)\n    if value==403:\n        return text_reason_403(w,at)\n    if value==404:\n        return text_reason_404(w,at)\n    if value==405:\n        return text_reason_405(w,at)\n    if value==406:\n        return text_reason_406(w,at)\n    if value==408:\n        return text_reason_408(w,at)\n    if value==413:\n        return text_reason_413(w,at)\n    if value==415:\n        return text_reason_415(w,at)\n    if value==431:\n        return text_reason_431(w,at)\n    if value==500:\n        return text_reason_500(w,at)\n    if value==503:\n        return text_reason_503(w,at)\n    return at\n\ndef weekday(w:mutbuf,at:u64,value:u64) -> u64:\n    if value==0:\n        return text_weekday_0(w,at)\n    if value==1:\n        return text_weekday_1(w,at)\n    if value==2:\n        return text_weekday_2(w,at)\n    if value==3:\n        return text_weekday_3(w,at)\n    if value==4:\n        return text_weekday_4(w,at)\n    if value==5:\n        return text_weekday_5(w,at)\n    if value==6:\n        return text_weekday_6(w,at)\n    return at\n\ndef month_name(w:mutbuf,at:u64,value:u64) -> u64:\n    if value==1:\n        return text_month_name_1(w,at)\n    if value==2:\n        return text_month_name_2(w,at)\n    if value==3:\n        return text_month_name_3(w,at)\n    if value==4:\n        return text_month_name_4(w,at)\n    if value==5:\n        return text_month_name_5(w,at)\n    if value==6:\n        return text_month_name_6(w,at)\n    if value==7:\n        return text_month_name_7(w,at)\n    if value==8:\n        return text_month_name_8(w,at)\n    if value==9:\n        return text_month_name_9(w,at)\n    if value==10:\n        return text_month_name_10(w,at)\n    if value==11:\n        return text_month_name_11(w,at)\n    if value==12:\n        return text_month_name_12(w,at)\n    return at\n\ndef close_chunk(o:mutbuf,w:mutbuf) -> u32:\n    if get(w,CR_CHUNK_FD)!=NONE:\n        return call(o,w,106,3,get(w,CR_CHUNK_FD),0,0,0,0,0,0)\n    return restart(o,w)\n'
LITERALS = {'reply_name': 'hia-http-response', 'version': 'HTTP/1.1 ', 'space': ' ', 'crlf': '\r\n', 'plain': 'content-type: text/plain; charset=utf-8\r\n', 'json': 'content-type: application/json\r\n', 'sse': 'content-type: text/event-stream\r\ncache-control: no-cache\r\n', 'allow_health': 'allow: GET,HEAD\r\n', 'allow_mcp': 'allow: GET, POST, DELETE\r\n', 'allow_post': 'allow: POST\r\n', 'length': 'content-length: ', 'close': 'connection: close\r\n', 'date': 'date: ', 'end': '\r\n\r\n', 'comma_space': ', ', 'gmt': ' GMT', 'reason_100': 'Continue', 'reason_200': 'OK', 'reason_202': 'Accepted', 'reason_204': 'No Content', 'reason_400': 'Bad Request', 'reason_401': 'Unauthorized', 'reason_403': 'Forbidden', 'reason_404': 'Not Found', 'reason_405': 'Method Not Allowed', 'reason_406': 'Not Acceptable', 'reason_408': 'Request Timeout', 'reason_413': 'Payload Too Large', 'reason_415': 'Unsupported Media Type', 'reason_431': 'Request Header Fields Too Large', 'reason_500': 'Internal Server Error', 'reason_503': 'Service Unavailable', 'weekday_0': 'Sun', 'weekday_1': 'Mon', 'weekday_2': 'Tue', 'weekday_3': 'Wed', 'weekday_4': 'Thu', 'weekday_5': 'Fri', 'weekday_6': 'Sat', 'month_name_1': 'Jan', 'month_name_2': 'Feb', 'month_name_3': 'Mar', 'month_name_4': 'Apr', 'month_name_5': 'May', 'month_name_6': 'Jun', 'month_name_7': 'Jul', 'month_name_8': 'Aug', 'month_name_9': 'Sep', 'month_name_10': 'Oct', 'month_name_11': 'Nov', 'month_name_12': 'Dec'}

